/**
 * Normalized pairing/bonding failure status.
 *
 * Mirrors `rblue_api::PairingStatus`; [`PairingStatus::Other`] preserves the
 * raw platform code.
 */

public enum PairingStatus: Equatable, Hashable {
    
    /**
     * The peer rejected the pairing request.
     */
    case rejected
    /**
     * The pairing procedure did not complete within its deadline.
     */
    case timedOut
    /**
     * PIN/passkey mismatch or MITM protection failure.
     */
    case authenticationFailed
    /**
     * A pairing procedure is already in progress for this device.
     */
    case inProgress
    /**
     * The peer or transport cannot pair (IO capability mismatch).
     */
    case notCapable
    /**
     * The platform returned a status code that does not normalize.
     */
    case other(
        /**
         * Raw platform pairing status code.
         */code: Int32
    )





}

#if compiler(>=6)
extension PairingStatus: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypePairingStatus: FfiConverterRustBuffer {
    typealias SwiftType = PairingStatus

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> PairingStatus {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .rejected
        
        case 2: return .timedOut
        
        case 3: return .authenticationFailed
        
        case 4: return .inProgress
        
        case 5: return .notCapable
        
        case 6: return .other(code: try FfiConverterInt32.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: PairingStatus, into buf: inout [UInt8]) {
        switch value {
        
        
        case .rejected:
            writeInt(&buf, Int32(1))
        
        
        case .timedOut:
            writeInt(&buf, Int32(2))
        
        
        case .authenticationFailed:
            writeInt(&buf, Int32(3))
        
        
        case .inProgress:
            writeInt(&buf, Int32(4))
        
        
        case .notCapable:
            writeInt(&buf, Int32(5))
        
        
        case let .other(code):
            writeInt(&buf, Int32(6))
            FfiConverterInt32.write(code, into: &buf)
            
        }
    }
}


