            )
        case 4: return .NotConnected
        case 5: return .Timeout
        case 6: return .Pairing(
            status: try FfiConverterTypePairingStatus.read(from: &buf)
            )
        case 7: return .Att(
            code: try FfiConverterUInt8.read(from: &buf), 
            handle: try FfiConverterOptionUInt16.read(from: &buf)
            )
        case 8: return .Platform(
