/**
 * Host-side receiver for adapter events and GATT notifications.
 *
 * Implemented on the foreign side (Kotlin object / Swift class) and
 * registered with [`Rblue::set_event_sink`]. Methods are invoked from the
 * facade's pump worker threads: implementations must not block, must not
 * re-enter the facade, and must not throw - an exception unwinds into the
 * pump and terminates event delivery. Buffering and drop accounting are the
 * binding layer's job (`callbackFlow(BUFFERED)` / `AsyncStream`; see the
 * crate documentation).
 */
public protocol EventSink: AnyObject, Sendable {
    
    /**
     * One adapter event (a serialized `rblue_api::AdapterEvent`): state
     * changes, discoveries, connection state. Values are opaque - parse the
     * JSON with the schema the `rblue-api` serde types define.
     */
    func onEvent(eventJson: String) 
    
    /**
     * One GATT notification/indication (a serialized
     * `rblue_api::Notification`), delivered only for subscribed
     * characteristics.
     */
    func onNotification(notificationJson: String) 
    
    /**
     * One local GATT server event (a serialized
     * `rblue_api::GattServerEvent`).
     */
    func onGattServerEvent(eventJson: String) 
    
}


// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceEventSink {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceEventSink = UniffiVTableCallbackInterfaceEventSink(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterCallbackInterfaceEventSink.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface EventSink: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterCallbackInterfaceEventSink.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface EventSink: handle missing in uniffiClone")
            }
        },
        onEvent: { (
            uniffiHandle: UInt64,
            eventJson: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterCallbackInterfaceEventSink.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.onEvent(
                     eventJson: try FfiConverterString.lift(eventJson)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        onNotification: { (
            uniffiHandle: UInt64,
            notificationJson: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterCallbackInterfaceEventSink.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.onNotification(
                     notificationJson: try FfiConverterString.lift(notificationJson)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        onGattServerEvent: { (
            uniffiHandle: UInt64,
            eventJson: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
